let sharedAudioCtx=null;function getAudioCtx(){try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return null;if(!sharedAudioCtx||sharedAudioCtx.state==='closed')sharedAudioCtx=new AC();return sharedAudioCtx}catch(e){return null}}async function unlockAudio(){const ctx=getAudioCtx();if(!ctx)return null;try{if(ctx.state==='suspended')await ctx.resume();const b=ctx.createBuffer(1,1,22050),src=ctx.createBufferSource();src.buffer=b;src.connect(ctx.destination);src.start(0)}catch(e){}return ctx}['touchstart','pointerdown','click'].forEach(type=>document.addEventListener(type,()=>{unlockAudio()},{once:true,passive:true,capture:true}));
